// What the Check-in tab reads again after a confirmed change (ADR-0079). The Weekly review and the optional AI insight
// have separate refresh keys because they read different data:
// - a check-in is a source of both: the review describes it, and the insight can become stale or be deleted;
// - movement is read by the review only (it is not an AI insight source), so a movement change refreshes the review and
//   never the insight, which therefore makes no request and cannot be regenerated by it.
// Neither changes the selected week: a refresh reads the week that is shown.

export interface CheckInRefreshKeys {
  /** Changes when the optional AI insight section should read its week again. */
  insight: number;
  /** Changes when the Weekly review section should read its week again. */
  review: number;
}

export type CheckInChange = 'check-in' | 'movement';

export const initialRefreshKeys: CheckInRefreshKeys = { insight: 0, review: 0 };

/** The keys after a confirmed save or deletion of a check-in or of movement. */
export function afterConfirmedChange(keys: CheckInRefreshKeys, change: CheckInChange): CheckInRefreshKeys {
  return change === 'check-in' ? { insight: keys.insight + 1, review: keys.review + 1 } : { ...keys, review: keys.review + 1 };
}
